  s=s[:a]+'''if(document.body.dataset.case){const c=cases.find(x=>x.id===document.body.dataset.case),section=$('#cases');if(c){const box=document.createElement('div');box.className='case-play';box.innerHTML=`<h3>${c.name}</h3><img class="play-art" src="${A+'case-'+c.id+'.svg'}" alt="Кейс ${c.name}"><p>${c.type==='allin'?'ALL IN · минимальный пакет — 10 кейсов':'Выбери количество'} · один кейс ✦ ${format(c.price)}</p><div class="play-controls" role="group" aria-label="Количество кейсов">${(c.type==='allin'?[10,50,100]:[1,2,3,5,10]).map(n=>`<button class="play-count ${n===(c.minCount||1)?'active':''}" data-amount="${n}" aria-pressed="${n===(c.minCount||1)}">${n}</button>`).join('')}</div><button class="btn btn-primary play-submit" id="playOpen">Открыть</button><p class="play-status" id="playStatus" role="status" aria-live="polite">Результат появится здесь · все призы сохраняются в профиле.</p><div class="roll-stack" id="rollStack"></div><div class="batch-actions" id="batchActions"></div><div class="roll-wins" id="rollWins"></div>`;section.insertBefore(box,section.querySelector('.case-detail'));let amount=c.minCount||1;const go=$('#playOpen'),status=$('#playStatus');let batch=[];function updatePlay(){go.textContent=`Открыть ${amount} · ✦ ${format(c.price*amount)}`;go.disabled=busy||state.balance<c.price*amount;go.title=go.disabled&&!busy?'Недостаточно демо-монет':''}box.querySelector('.play-controls').addEventListener('click',e=>{let b=e.target.closest('[data-amount]');if(!b||busy)return;amount=Number(b.dataset.amount);box.querySelectorAll('[data-amount]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});updatePlay()});function updateBatch(){let owned=batch.filter(x=>state.inventory.some(i=>i.uid===x.uid));$('#batchActions').innerHTML=owned.length?`<button class="btn btn-ghost" id="sellBatch">Продать все из открытия (${owned.length}) · ✦ ${format(owned.reduce((a,x)=>a+P[x.id].value,0))}</button><a class="btn btn-ghost" href="profile.html">В профиль →</a>`:'';$('#rollWins').innerHTML=batch.map(x=>{let p=P[x.id],sold=!owned.some(y=>y.uid===x.uid);return `<article class="roll-win">${itemMarkup(p)}<strong>${p.name}</strong><small>✦ ${format(p.value)}</small><button data-win-sell="${x.uid}" ${sold?'disabled':''}>${sold?'Продано':'Продать сразу'}</button></article>`}).join('')}box.addEventListener('click',e=>{let sell=e.target.closest('[data-win-sell]');if(sell&&!busy){let idx=state.inventory.findIndex(i=>i.uid===sell.dataset.winSell);if(idx<0)return;state.balance+=P[state.inventory[idx].id].value;state.inventory.splice(idx,1);save();render();updateBatch();updatePlay();notify('Предмет продан')}if(e.target.id==='sellBatch'&&!busy){let ids=new Set(batch.map(x=>x.uid));let owned=state.inventory.filter(x=>ids.has(x.uid));if(!owned.length)return;let total=owned.reduce((a,x)=>a+P[x.id].value,0);if(!confirm(`Продать ${owned.length} предметов за ✦ ${format(total)}?`))return;state.balance+=total;state.inventory=state.inventory.filter(x=>!ids.has(x.uid));save();render();updateBatch();updatePlay();notify('Продано за ✦ '+format(total))}});go.addEventListener('click',()=>{if(busy)return;let count=amount,total=c.price*count;if(count<(c.minCount||1)||state.balance<total){notify('Недостаточно демо-монет');return}busy=true;state.balance-=total;batch=Array.from({length:count},()=>({id:chooseDrop(c).id,uid:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,12)}));state.inventory.push(...batch);save();render();updatePlay();$('#batchActions').replaceChildren();$('#rollWins').replaceChildren();let stack=$('#rollStack');stack.replaceChildren();status.textContent=`Открываем ${count} кейсов · барабаны вращаются…`;let pool=c.drops.map(([id])=>P[id]);let lanes=[];for(let j=0;j<Math.min(5,count);j++){let lane=document.createElement('div');lane.className='roll-lane';let strip=document.createElement('div');strip.className='roll-strip';let seq=Array.from({length:26},()=>pool[Math.floor(Math.random()*pool.length)]);seq[20]=P[batch[j].id];strip.innerHTML=seq.map(p=>`<div class="roll-tile"><img src="${itemImage(p)}" alt=""><span>${p.name.split(' · ').at(-1).slice(0,12)}</span></div>`).join('');lane.append(strip);stack.append(lane);lanes.push([lane,strip])}if(count>5){let note=document.createElement('p');note.className='roll-count-note';note.textContent=`Показаны 5 из ${count} барабанов · все ${count} результатов появятся ниже`;stack.append(note)}requestAnimationFrame(()=>requestAnimationFrame(()=>lanes.forEach(([lane,strip],j)=>{let w=strip.firstElementChild.getBoundingClientRect().width;strip.style.transition=`transform ${2.5+j*.2}s cubic-bezier(.12,.68,.14,1)`;strip.style.transform=`translateX(-${20*w+w/2-lane.clientWidth/2}px)`})));setTimeout(()=>{busy=false;render();updatePlay();status.textContent=`Открыто ${count} кейсов! Продай призы прямо здесь или оставь в профиле.`;updateBatch();notify('Открыто кейсов: '+count)},3700)});updatePlay();let old=section.querySelector('#caseGrid [data-case]');if(old)old.remove()}}''' + s[b:]
